css:
/* Sage / Forest & Porcelain — Clutter-Free 60fps Cinema Stage UI (Zero blur filters, zero shadow transitions) */

*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1920px;height:1080px;overflow:hidden;background:#0D1612;color:#EFF5F1;font-family:"SamsungOne","Roboto","Helvetica Neue",Arial,sans-serif;-webkit-font-smoothing:antialiased}
#backdrop{position:fixed;top:0;left:0;right:0;bottom:0;background:#0D1612 center/cover no-repeat;overflow:hidden}
.bd-layer{position:absolute;top:0;left:0;right:0;bottom:0;display:none}
#root{position:relative;height:100%;padding:44px 88px 0;overflow:hidden}
h1{font-size:52px;font-weight:700;letter-spacing:-.6px}
h2{font-size:22px;font-weight:600;margin:0 0 14px;letter-spacing:.6px;text-transform:uppercase;color:#9EB4A6}
.row-active>h2{color:#EFF5F1}
.muted{color:#9EB4A6}
.brand{display:flex;align-items:center;gap:14px;font-size:26px;font-weight:700;letter-spacing:-.2px;color:#EFF5F1}
.brand i{width:34px;height:34px;border-radius:10px;background:#B4D2BD;display:inline-block;box-shadow:inset 0 0 0 8px #1F4233}
.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;height:52px}
.glass{background:rgba(19,32,26,.94);border:1px solid rgba(180,210,189,.16);border-radius:18px}

/* Hardware-only transform transitions (120ms, zero box-shadow animation) */
.focusable{outline:none;transition:transform .12s cubic-bezier(.2,1,.3,1),border-color .12s ease,background-color .12s ease}
.focusable.focused{transform:translate3d(0,-4px,0) scale(1.04);border-color:#B4D2BD!important;box-shadow:0 0 0 3px #B4D2BD;z-index:4}

.btn{display:inline-flex;align-items:center;gap:10px;height:54px;padding:0 28px;border-radius:27px;font-size:22px;font-weight:600;background:rgba(24,40,32,.92);color:#EFF5F1;border:1.5px solid rgba(180,210,189,.16)}
.btn.primary{background:#B4D2BD;color:#102D20;border-color:#B4D2BD;font-weight:700}
.btn.focused{transform:translate3d(0,-2px,0) scale(1.03)}

/* Clutter-free Split Stage: Hero stays anchored at top, active shelf glides below */
.hero{max-width:960px;height:310px;padding:6px 0 14px;margin-bottom:14px;position:relative;display:flex;flex-direction:column;justify-content:center}
.hero-body{max-width:920px}
.hero-eyebrow{font-size:16px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:#B4D2BD;margin-bottom:8px}
.hero-title{font-size:56px;font-weight:800;line-height:1.05;letter-spacing:-1px;color:#EFF5F1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.meta{display:flex;align-items:center;flex-wrap:wrap;gap:0;font-size:20px;font-weight:500;color:#9EB4A6;margin-top:10px}
.meta span{padding:0;background:none;border:none;border-radius:0}
.meta span+span::before{content:"\00a0\00b7\00a0\00a0";color:#7A9685}
.hero-desc{max-width:780px;font-size:21px;line-height:1.45;color:#9EB4A6;margin:12px 0 20px;max-height:60px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}

.rows{height:610px;overflow:hidden;position:relative}
.rows-inner{transition:transform .15s cubic-bezier(.2,1,.3,1);will-change:transform}
.row{margin-bottom:34px;transition:opacity .14s ease}
.row.row-above{opacity:0;pointer-events:none}
.row.row-next{opacity:.38}
.row.row-far{opacity:0;pointer-events:none}

.track{display:flex;gap:22px;transition:transform .14s cubic-bezier(.2,1,.3,1);padding:8px 4px;will-change:transform}

/* Pure Artwork Cards — zero bottom text banner clutter */
.card{flex:0 0 auto;width:204px;border-radius:16px;overflow:hidden;background:#13201A;border:2px solid rgba(255,255,255,.06);position:relative}
.card .art{width:204px;height:306px;background:#1D2F26 center/cover no-repeat}
.card.wide{width:368px}
.card.wide .art{width:368px;height:207px}
.card:not(.ep-card)>.t,.rank-poster>.t{font-size:0;line-height:0;height:0;padding:0;margin:0;opacity:0;overflow:hidden;border:0}
.prog{position:absolute;left:0;right:0;bottom:0;height:5px;background:rgba(255,255,255,.18)}
.prog b{display:block;height:100%;background:#B4D2BD}

/* Sleek Horizontal Streaming Platform Pills */
.chip{flex:0 0 auto;height:66px;min-width:176px;padding:0 24px 0 12px;border-radius:33px;display:flex;flex-direction:row;align-items:center;justify-content:flex-start;gap:14px;background:rgba(21,36,27,.92);border:1.5px solid rgba(180,210,189,.16)}
.chip .cn{font-size:21px;font-weight:600;color:#EFF5F1;white-space:nowrap}
.logo{display:inline-flex;align-items:center;justify-content:center;border-radius:22px;flex:0 0 auto}
.logo.mono{background:#B4D2BD;color:#102D20;font-weight:700;font-size:20px}
.plogo .logo{border-radius:26px}
.plogo .logo.mono{font-size:42px}

.filters{display:flex;gap:14px;margin-bottom:16px}
.pill{height:48px;padding:0 24px;border-radius:24px;font-size:20px;font-weight:600;display:flex;align-items:center;background:rgba(21,36,27,.92);border:1.5px solid rgba(180,210,189,.16);color:#9EB4A6}
.pill.on{background:#1F4233;color:#B4D2BD;border-color:#B4D2BD}
.pill-sep{width:18px;flex:0 0 18px}

/* Quick Connect Sign-In */
.code{display:flex;gap:16px;margin:32px 0}
.code span{width:104px;height:132px;border-radius:20px;background:#13201A;border:2px solid #B4D2BD;font-size:78px;font-weight:700;display:flex;align-items:center;justify-content:center;color:#B4D2BD}
.signin{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:1060px;padding:64px 74px;text-align:left}
.steps{font-size:24px;line-height:1.65;color:#9EB4A6}.steps b{color:#EFF5F1}

/* Clutter-Free Detail Screen */
.detail{max-width:1040px;padding-top:2px;margin-bottom:18px}
.detail p{font-size:21px;line-height:1.45;color:#9EB4A6;margin:10px 0 18px;max-height:92px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical}
.detail-credits{font-size:19px;color:#9EB4A6;margin:-4px 0 16px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.detail-credits b{color:#EFF5F1;font-weight:600}
.actions{display:flex;gap:14px}

/* Episode Cards & Live Episode Preview Bar */
.ep-card{width:368px}
.ep-card .art{width:368px;height:196px;position:relative}
.ep-badge{position:absolute;top:10px;left:10px;padding:3px 10px;border-radius:8px;font-size:14px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;background:#B4D2BD;color:#102D20}
.ep-badge.watched{background:rgba(16,27,23,.9);color:#B4D2BD;border:1px solid #B4D2BD}
.ep-runtime{position:absolute;bottom:10px;right:10px;padding:2px 8px;border-radius:6px;font-size:14px;font-weight:600;background:rgba(13,22,18,.88);color:#9EB4A6}
.ep-info{padding:10px 14px 12px;background:#13201A}
.ep-title{font-size:19px;font-weight:600;color:#EFF5F1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center;gap:8px}
.ep-num{display:inline-flex;align-items:center;justify-content:center;padding:2px 8px;border-radius:6px;font-size:14px;font-weight:700;background:#1F4233;color:#B4D2BD;flex:0 0 auto}
.ep-sub{font-size:15px;line-height:1.35;color:#9EB4A6;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ep-preview{max-width:1240px;padding:12px 20px;margin:0 0 14px;border-radius:14px;background:rgba(19,32,26,.92);border:1px solid rgba(180,210,189,.16)}
.ep-prev-head{display:flex;align-items:center;gap:14px;margin-bottom:2px}
.ep-prev-tag{font-size:19px;font-weight:700;color:#B4D2BD}
.ep-prev-meta{font-size:16px;font-weight:600;color:#9EB4A6}
.ep-prev-desc{font-size:18px;line-height:1.35;color:#9EB4A6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* Cast & Crew Minimal Pills */
.person-card{flex:0 0 auto;width:176px;padding:16px 12px;border-radius:16px;background:rgba(19,32,26,.92);border:1.5px solid rgba(180,210,189,.16);display:flex;flex-direction:column;align-items:center;text-align:center;gap:6px}
.person-avatar{width:88px;height:88px;border-radius:44px;background:#1F4233 center/cover no-repeat;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700;color:#B4D2BD;margin-bottom:2px}
.p-name{font-size:18px;font-weight:600;color:#EFF5F1;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.p-role{font-size:15px;color:#9EB4A6;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}

/* Top 10 Trending Today — Clean Minimalist Number + Pure Poster */
.card.rank-card{width:254px;display:flex;align-items:flex-end;background:transparent;border:none!important;box-shadow:none!important;overflow:visible;position:relative;padding-left:50px}
.card.rank-card.focused{transform:translate3d(0,-4px,0) scale(1.04);box-shadow:none!important}
.rank-num{position:absolute;left:-2px;bottom:8px;width:66px;text-align:right;padding-right:6px;font-size:118px;font-weight:900;line-height:.82;letter-spacing:-6px;color:rgba(19,32,26,.95);-webkit-text-stroke:2.5px #7A9685;pointer-events:none;z-index:1}
.card.rank-card.focused .rank-num{color:#B4D2BD;-webkit-text-stroke:0}
.rank-poster{width:204px;border-radius:16px;overflow:hidden;background:#13201A;border:2px solid rgba(255,255,255,.06);position:relative;z-index:2}
.card.rank-card.focused .rank-poster{border-color:#B4D2BD;box-shadow:0 0 0 3px #B4D2BD}
.rank-poster .art{width:204px;height:306px;position:relative}
.rank-badge{font-size:0;line-height:0;padding:0;border:0;opacity:0;pointer-events:none;position:absolute}
.nextup-card .art{position:relative}

/* Search, Player & Modals */
.searchbox{height:72px;width:920px;border-radius:36px;padding:0 32px;font-size:28px;display:flex;align-items:center;margin-bottom:20px}
.keys{display:grid;grid-template-columns:repeat(13,68px);gap:8px;margin-bottom:24px}
.key{height:56px;border-radius:12px;background:#13201A;border:1.5px solid rgba(180,210,189,.16);display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:600}
.key.w2{grid-column:span 2}
#player{position:fixed;top:0;left:0;right:0;bottom:0;background:#000}
#player video,#player object{width:100%;height:100%}
.osd{position:absolute;left:88px;right:88px;bottom:54px;padding:26px 36px;transition:opacity .2s ease}
.osd .bar{height:6px;border-radius:3px;background:#283E33;margin:16px 0}
.osd .bar b{display:block;height:100%;border-radius:3px;background:#B4D2BD}
.osd .row2{display:flex;justify-content:space-between;font-size:20px;color:#9EB4A6}
.osd.hide{opacity:0}
#toast{position:fixed;right:56px;bottom:44px;padding:16px 26px;border-radius:14px;background:rgba(19,32,26,.94);border:1px solid #B4D2BD;font-size:21px;opacity:0;transition:opacity .18s ease;z-index:30}
#toast.show{opacity:1}
.empty{font-size:22px;color:#9EB4A6;padding:16px 0}
.state{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:920px;padding:54px 64px}
.state p{font-size:23px;margin:16px 0 28px}
.buffer{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);padding:16px 28px;border-radius:14px;background:rgba(13,22,18,.92);font-size:23px;display:none}
.menu{position:absolute;right:56px;top:56px;bottom:200px;width:480px;padding:30px;overflow:hidden}
.opt{height:54px;border-radius:12px;padding:0 20px;display:flex;align-items:center;font-size:21px;margin-bottom:6px}
.opt.on{background:#1F4233;color:#B4D2BD}
.opt.focused{transform:none;box-shadow:inset 0 0 0 3px #B4D2BD}
.ver-badge{font-size:16px;font-weight:600;padding:3px 10px;border-radius:10px;background:rgba(255,255,255,.06);color:#9EB4A6}
.btn.has-update{background:#1F4233;color:#B4D2BD;border-color:#B4D2BD}
.ota-banner{margin:0 0 14px;padding:14px 24px;display:flex;justify-content:space-between;align-items:center;font-size:20px;border-color:#B4D2BD;background:rgba(31,66,51,.94)}
.modal-backdrop{position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(10,16,13,.88);z-index:20;display:flex;align-items:center;justify-content:center}
.modal-card{width:980px;padding:52px 60px}
.ota-status{font-size:22px;line-height:1.45;color:#9EB4A6;margin-top:20px;padding:18px 22px;border-radius:14px;background:#13201A;border:1px solid rgba(180,210,189,.16)}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}.focusable.focused{transform:none}}
